# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows


def shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))


def names(rows):
    return [row.split(":")[0] for row in rows]


BUSY = [
    shift("Bo", "mon", 9, 12),
    shift("Ana", "mon", 8, 16),
    shift("Ana", "tue", 8, 12),
    shift("Bo", "tue", 9, 10)
]
TIES = [
    shift("Cy", "mon", 8, 10),
    shift("Bo", "mon", 8, 9),
    shift("Bo", "tue", 8, 9),
    shift("Al", "mon", 8, 10)
]
ODD = Shift("Ana", "mon", Span(540, 625))


class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows(BUSY)
        self.assertEqual(rows, [
            "Ana: 2 shifts, 12.0 hours",
            "Bo: 2 shifts, 4.0 hours"
        ])

    def test_hours_use_one_decimal_place(self):
        rows = timesheet_rows([ODD])
        self.assertEqual(rows, ["Ana: 1 shift, 1.4 hours"])

    def test_ties_break_on_count_then_name(self):
        rows = timesheet_rows(TIES)
        self.assertEqual(names(rows), ["Bo", "Al", "Cy"])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.assertRaises(ValueError):
                timesheet_rows([shift(name, "mon", 8, 9)])


if __name__ == "__main__":
    unittest.main()
